async function getContext(owner){
  if(contextOwner!==owner){contextOwner=owner;contextPromise=null;}
  if(!contextPromise)contextPromise=(async()=>{const service=createSupplierWorkspace(owner);const data=await service.load();return {service,data,owner,alive:true};})().catch(error=>{contextPromise=null;throw error;});
  return contextPromise;
}
onSessionChange(({user})=>{if(contextOwner&&user?.id!==contextOwner){contextPromise?.then(ctx=>{ctx.alive=false;}).catch(()=>{});contextPromise=null;contextOwner=null;document.querySelectorAll('.sw-dialog').forEach(d=>d.close());}});
export async function mountSupplierTool(root,key,owner){
  const waiting=el('p','Opening your workspace…','sd-note');root.append(waiting);
  let ctx;try{ctx=await getContext(owner);}catch(error){waiting.textContent=error.message;root.append(btn('Try again',()=>{root.replaceChildren();void mountSupplierTool(root,key,owner);}));return;}
  if(!root.isConnected||!ctx.alive)return;waiting.remove();
  if(ctx.service.mode==='local')root.append(el('p','Review mode · Changes are saved in this browser. Publishing and shared account saves unlock after the Supabase setup.','sw-review-banner'));
  const status=el('p','','sw-status');status.setAttribute('role','status');root.append(status);
  async function run(task,message){
    if(root.dataset.busy==='true'||!ctx.alive)return false;root.dataset.busy='true';
    const disabled=Array.from(root.querySelectorAll('button,input,select,textarea')).map(n=>[n,n.disabled]);disabled.forEach(([n])=>{n.disabled=true;});status.textContent='Saving…';status.classList.remove('sw-error');
    try{await task();if(!ctx.alive)return false;status.textContent=message;window.dispatchEvent(new CustomEvent('wedsparks:supplier-workspace-changed'));return true;}
    catch(error){if(ctx.alive){status.textContent=error.message;status.classList.add('sw-error');}return false;}
    finally{disabled.forEach(([n,v])=>{if(n.isConnected)n.disabled=v;});delete root.dataset.busy;}
  }
  const save=(message='Saved.')=>run(()=>ctx.service.save(ctx.data),message);
  if(key==='storefront')await storefront(root,ctx,status,run,save);
  if(key==='pricing-packages')packages(root,ctx,run);
  if(key==='availability')availability(root,ctx,save);
  if(key==='bookings')bookings(root,ctx,run);
  if(key==='reviews')await reviews(root,ctx);
}
